using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.Spatial;
using TripPlanner.Api.DTO;
using TripPlanner.Api.Models;
using TripPlanner.Api.Services.Documents;
using TripPlanner.Api.Services.Flights;

namespace TripPlanner.Api.Tests.Database;

public sealed partial class InMemoryPlannerDb
{
    // Test-only restoration of the portable document into disposable domain storage.
    // Validators and derived transfers are regenerated by the real server projection.
    internal Trip SeedEvalDocument(User connected, TripDocument document)
    {
        var options = TripResourceProjection.JsonOptions;
        var tripId = Guid.NewGuid();
        var places = document.Places.ToDictionary(p => p["id"]!.GetValue<string>());
        var items = document.Itinerary["items"]!.AsArray().OfType<JsonObject>().ToArray();
        var owner = document.People.Single(p => p["isOwner"]!.GetValue<bool>());
        var ownerId = Guid.Parse(owner["id"]!.GetValue<string>());
        Guid Person(Guid id) => id == ownerId ? connected.Id : id;
        var home = places[document.OriginPlaceId];
        GeoJsonPoint? Point(JsonObject? place)
        {
            var coordinates = place?["location"]?["coordinates"]?.AsArray();
            return coordinates is null
                ? null
                : new(
                    "Point",
                    GeographyPoint.Create(
                        coordinates[1]!.GetValue<double>(),
                        coordinates[0]!.GetValue<double>()
                    )
                );
        }
        var trip = new Trip(
            tripId,
            connected.Id,
            document.Name,
            document.Description,
            JsonSerializer.SerializeToElement(document.Preferences["constraints"], options),
            document.CreatedAt,
            document.UpdatedAt
        );
        lock (_tripLock)
        {
            _trips[tripId] = trip;
            foreach (var person in document.People)
            {
                var id = Person(Guid.Parse(person["id"]!.GetValue<string>()));
                var email = id == connected.Id ? connected.Email : $"{id:N}@eval.example";
                _users[email] = new(
                    id,
                    "google",
                    email,
                    person["name"]!.GetValue<string>(),
                    person["homeCityName"]?.GetValue<string>(),
                    Point(home) is { } point
                        ? new(point.Position.Longitude, point.Position.Latitude)
                        : null,
                    [],
                    document.CreatedAt,
                    document.UpdatedAt
                );
            }
            foreach (var group in document.Preferences["groups"]!.AsArray().OfType<JsonObject>())
            {
                var id = Guid.Parse(group["id"]!.GetValue<string>());
                var ids = group["personIds"]!
                    .AsArray()
                    .Select(p => Person(Guid.Parse(p!.GetValue<string>())))
                    .ToArray();
                _parties[id] = new(id, tripId, ids)
                {
                    MemberRoles = document.People.ToDictionary(
                        p => Person(Guid.Parse(p["id"]!.GetValue<string>())),
                        p => Enum.Parse<PartyRole>(p["role"]!.GetValue<string>())
                    ),
                };
            }
            foreach (var place in document.Places.Where(p => p["destinationId"] is not null))
            {
                var city = place["destinationId"]!.GetValue<string>();
                var point = Point(place)!;
                var preferences = document.Preferences["destinations"]!
                    .AsArray()
                    .Single(p => p!["destinationId"]!.GetValue<string>() == city)!;
                _destinationPlaces[(tripId, city)] = new(
                    tripId,
                    city,
                    place["name"]!.GetValue<string>(),
                    place["countryCode"]!.GetValue<string>(),
                    place["timeZone"]!.GetValue<string>(),
                    point.Position.Longitude,
                    point.Position.Latitude,
                    Guid.NewGuid().ToString("N")
                )
                {
                    Constraints = JsonSerializer.SerializeToElement(
                        preferences["constraints"],
                        options
                    ),
                };
                _activityPreferences[(tripId, "destination", city)] = new(
                    preferences["activities"]!.Deserialize<ActivityPreferences>(options)!
                );
            }
            _activityPreferences[(tripId, "trip", "")] = new(
                document.Preferences["activities"]!.Deserialize<ActivityPreferences>(options)!
            );
            foreach (var visit in items.Where(i => i["kind"]!.GetValue<string>() == "visit"))
            {
                var id = Guid.Parse(visit["id"]!.GetValue<string>());
                _destinationVisits[id] = new(
                    tripId,
                    visit["destinationId"]!.GetValue<string>(),
                    id,
                    visit["order"]!.GetValue<int>(),
                    visit["start"] is null
                        ? null
                        : DateOnly.Parse(visit["start"]!.GetValue<string>()),
                    visit["end"] is null ? null : DateOnly.Parse(visit["end"]!.GetValue<string>())
                );
            }
            foreach (var lodging in items.Where(i => i["kind"]!.GetValue<string>() == "lodging"))
            {
                var stayId = Guid.Parse(lodging["visitId"]!.GetValue<string>());
                var city = _destinationVisits[stayId].CityId;
                var place = places[lodging["placeId"]!.GetValue<string>()];
                var hotelId = Guid.NewGuid();
                _hotels[hotelId] = new(
                    hotelId,
                    tripId,
                    lodging["name"]!.GetValue<string>(),
                    null,
                    Point(place)!,
                    null,
                    1
                );
                _stayLocations[(tripId, city, stayId)] = new(
                    "Feature",
                    stayId.ToString(),
                    Point(place),
                    new(lodging["name"]!.GetValue<string>(), HotelId: hotelId)
                );
            }
            foreach (var item in items.Where(i => i["kind"]!.GetValue<string>() == "activity"))
            {
                var id = Guid.Parse(item["id"]!.GetValue<string>());
                var properties = item.DeepClone().AsObject();
                properties["duration"] = item["estimatedDuration"]?.DeepClone();
                var place = item["placeId"] is null
                    ? null
                    : places[item["placeId"]!.GetValue<string>()];
                _activities[id] = new(
                    id,
                    tripId,
                    item["destinationId"]!.GetValue<string>(),
                    Point(place),
                    properties.Deserialize<ActivityProperties>(options)!,
                    document.CreatedAt,
                    document.UpdatedAt
                );
            }
            foreach (
                var destination in document.Preferences["destinations"]!
                    .AsArray()
                    .OfType<JsonObject>()
            )
            {
                var city = destination["destinationId"]!.GetValue<string>();
                var schedule = destination["schedule"]!.DeepClone().AsObject();
                var activities = items
                    .Where(i =>
                        i["kind"]!.GetValue<string>() == "activity"
                        && i["destinationId"]!.GetValue<string>() == city
                    )
                    .ToArray();
                foreach (
                    var (field, selection) in new[]
                    {
                        ("selectedActivityIds", "Selected"),
                        ("excludedActivityIds", "Excluded"),
                    }
                )
                {
                    schedule[field] = new JsonArray(
                        activities
                            .Where(a => a["selection"]!.GetValue<string>() == selection)
                            .Select(a => a["id"]!.DeepClone())
                            .ToArray()
                    );
                }
                schedule["rules"] = new JsonArray(
                    activities
                        .Where(a => a["rule"] is not null)
                        .Select(a => a["rule"]!.DeepClone())
                        .ToArray()
                );
                var plan = schedule.Deserialize<ActivityPlan>(options)!;
                _activityPlans[(tripId, city)] = new(
                    plan,
                    new("unknown", [], [], [], 0, document.UpdatedAt),
                    1,
                    0,
                    document.UpdatedAt
                );
            }
            foreach (
                var source in document.Preferences["flightChoices"]!.AsArray().OfType<JsonObject>()
            )
            {
                var partyId = Guid.Parse(source["groupId"]!.GetValue<string>());
                var journeys = source["journeys"]!.AsArray().OfType<JsonObject>().ToArray();
                var fares = new List<FareSearchResult>();
                foreach (var booking in source["bookings"]!.AsArray().OfType<JsonObject>())
                {
                    var keys = booking["legKeys"]!
                        .AsArray()
                        .Select(k => k!.GetValue<string>())
                        .ToHashSet();
                    var legs = journeys
                        .Select(j => JsonSerializer.SerializeToElement(j["details"], options))
                        .Where(l => keys.Contains(FlightChoiceRoute.FlightKey(l)!))
                        .ToArray();
                    var segments = legs[0].GetProperty("segments");
                    var departure = DateOnly.Parse(
                        segments[0].GetProperty("departure_time_local").GetString()![..10]
                    );
                    var request = new IgnavFareRequest(
                        segments[0].GetProperty("departure_airport").GetString()!,
                        segments[segments.GetArrayLength() - 1]
                            .GetProperty("arrival_airport")
                            .GetString()!,
                        departure,
                        departure,
                        _parties[partyId].UserIds.Count,
                        "economy",
                        "US",
                        null,
                        "oneWay"
                    );
                    fares.Add(
                        new(
                            partyId,
                            "eval:" + booking["ignavId"]!.GetValue<string>(),
                            request,
                            JsonSerializer.SerializeToElement(
                                new
                                {
                                    itineraries = new[]
                                    {
                                        new
                                        {
                                            ignav_id = booking["ignavId"]!.GetValue<string>(),
                                            price = booking["price"],
                                            legs,
                                        },
                                    },
                                },
                                options
                            ),
                            document.UpdatedAt,
                            document.UpdatedAt
                        )
                    );
                }
                _flightChoices[(tripId, partyId)] = new(
                    partyId,
                    source["legKeys"]!.Deserialize<string?[]>(options)!,
                    source["nextOrigins"]!.Deserialize<string[]>(options)!
                )
                {
                    PurchasedOfferIds = source["purchasedOfferIds"]!.Deserialize<string[]>(
                        options
                    )!,
                    SavedFares = fares.ToArray(),
                };
            }
        }
        return trip;
    }
}
